MongoClientSettings settings = MongoClientSettings.builder()
    .applyConnectionString(new ConnectionString("mongodb://host1:27017,host2:27017,host3:27017/?replicaSet=rs0"))
    .readPreference(ReadPreference.secondaryPreferred())
    .writeConcern(WriteConcern.MAJORITY)
    .build();
MongoClient mongoClient = MongoClients.create(settings);
MongoDatabase database = mongoClient.getDatabase("production");
MongoCollection<Document> collection = database.getCollection("orders");
collection.insertOne(new Document("item", "A100").append("qty", 5));
